/**
 * Builds src/data/gdpHistory.ts — real GDP history per country, for the
 * sparkline the Dashboard draws on each country card.
 *
 * The series it replaced was generated by a formula: each country's current
 * GDP multiplied by 0.88, 0.91, 0.94, 0.97, 1.00 across five fixed years,
 * charted as if it were history. This writes what the World Bank actually
 * reports, and writes nothing where it reports nothing.
 *
 * Source: World Bank indicator NY.GDP.MKTP.CD, "GDP (current US$)", which the
 * site already uses live for current GDP. Values are converted to billions of
 * US dollars, the unit the rest of the dataset uses. Only years with a figure
 * are included, so a country with a short series gets a short sparkline and a
 * country with none gets no chart at all.
 *
 *   node build-gdp-history.cjs
 */
const fs = require("fs");
const os = require("os");
const path = require("path");
const { execSync } = require("child_process");

const OUT = path.join(__dirname, "src/data/gdpHistory.ts");
const CACHE = path.join(os.tmpdir(), "country-reference-cache");
const YEARS = 8; // 2018 onwards at the time of writing: enough to read a trend
const INDICATOR = "NY.GDP.MKTP.CD";
fs.mkdirSync(CACHE, { recursive: true });

function loadCountries() {
  const bundle = path.join(CACHE, "countriesData.cjs");
  execSync(`npx esbuild src/data/countriesData.ts --bundle --format=cjs --platform=node --log-level=error --outfile="${bundle}"`, { cwd: __dirname, stdio: "inherit" });
  delete require.cache[bundle];
  return require(bundle).countriesData;
}

(async () => {
  const countries = loadCountries();
  const url = `https://api.worldbank.org/v2/country/all/indicator/${INDICATOR}?format=json&mrv=${YEARS}&per_page=25000`;
  const res = await fetch(url, { headers: { "User-Agent": "commonsphere-data-build/1.0 (+https://github.com/commonsphere1-sketch/commonsphere)" } });
  if (!res.ok) throw new Error(`World Bank: HTTP ${res.status}`);
  const json = await res.json();
  if (!Array.isArray(json) || !json[1]) throw new Error("World Bank returned no rows: " + JSON.stringify(json).slice(0, 200));

  // The "all countries" call also returns aggregates (World, Euro area); only
  // codes in the dataset are kept.
  const wanted = new Set(countries.map((c) => c.code));
  const byCode = new Map();
  for (const row of json[1]) {
    if (row.value === null || !wanted.has(row.country.id)) continue;
    if (!byCode.has(row.country.id)) byCode.set(row.country.id, []);
    byCode.get(row.country.id).push({ year: row.date, gdp: row.value / 1e9 });
  }
  for (const series of byCode.values()) series.sort((a, b) => +a.year - +b.year);

  const round = (v) => (Math.abs(v) >= 100 ? Math.round(v) : Number(v.toFixed(1)));
  const body = [...byCode.entries()]
    .filter(([, s]) => s.length >= 2) // one point is not a trend
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([code, s]) => `  ${code}: [${s.map((p) => `{ year: "${p.year}", gdp: ${round(p.gdp)} }`).join(", ")}],`)
    .join("\n");

  const covered = [...byCode.keys()].filter((c) => byCode.get(c).length >= 2);
  const missing = countries.filter((c) => !covered.includes(c.code));
  const today = new Date().toISOString().slice(0, 10);
  fs.writeFileSync(OUT, `/**
 * GDP history per country, in billions of current US dollars.
 *
 * GENERATED by build-gdp-history.cjs on ${today} — do not edit by hand; change
 * the script and re-run it. Source: World Bank indicator ${INDICATOR},
 * "GDP (current US\\$)", most recent ${YEARS} years, aggregates excluded.
 *
 * Only years the World Bank reports a figure for are listed, so a series may be
 * shorter for some countries. ${missing.length} of the dataset's ${countries.length} countries have no
 * usable series and are absent here${missing.length ? ` (${missing.map((c) => c.code).join(", ")})` : ""};
 * countriesData.ts leaves their trends empty, and the pages draw no chart
 * rather than a made-up one.
 */
export const GDP_HISTORY_SOURCE = {
  label: "World Bank — GDP (current US$)",
  url: "https://data.worldbank.org/indicator/${INDICATOR}",
  retrieved: "${today}",
};

export const GDP_HISTORY: Record<string, { year: string; gdp: number }[]> = {
${body}
};
`);
  console.log(`wrote ${path.relative(__dirname, OUT)}: ${covered.length} countries with a series; ${missing.length} without (${missing.map((c) => c.code).join(", ") || "none"})`);
})().catch((e) => { console.error(e); process.exit(1); });
